/*
	LaTeX renderer for marked.js built-in tokens.

	This module exports a renderer object suitable for passing to
	marked.use({ renderer: latexRenderer }).  It covers the core
	structural tokens: paragraphs, headings, emphasis, bold, code,
	links, images, lists, blockquotes, horizontal rules, and line breaks.

	Tokens produced by custom extensions (e.g. /italics/, ==highlight==)
	are handled in their own extension renderers, not here.
*/

import { configManager } from './config-manager.js';
import { requirePackage } from './preamble.js';
import { latexGraphic } from './latex-graphics.js';
import { PYGMENTS_LEXERS } from './pygments-lexers.js';
import { addWarning, getWarnings } from './warnings.js';
import { escapeLatexText as escapeLatex, escapeTexText } from './latex-escape.js';
import { commandForDepth } from './sectioning.js';
import { marked } from './utils.js';

// Candidate \mintinline delimiters, tried in order. \mintinline takes its code
// verbatim between a delimiter pair (like \verb), so the delimiter just has to
// be a character the code does not contain — that is what lets inline code keep
// literal braces, backslashes, %, & and so on.
const MINTINLINE_DELIMS = ['|', '!', '+', '@', '/', ':', ';', '"', "'", '~', '?', '='];

// The language to hand minted for code written in `lang` — the first word of
// a fence's info string (```js title=x → js), else the `Code language`
// default. A language minted's Pygments has no lexer for (an Obsidian fence:
// dataview, tasks, query, kanban, base, mermaid, ad-note…) stops the compile —
// "no lexer for alias" — so it becomes `text`, printed verbatim, with one
// warning per language per build. The lexer list is the Pygments TeX Live's
// minted bundles (pygments-lexers.js, generated by scripts/pygments-lexers.py).
function mintedLanguage(lang) {
	const name = String(lang ?? '').trim().split(/\s+/)[0]
		|| configManager.get('Code language') || 'text';
	if (PYGMENTS_LEXERS.has(name.toLowerCase())) return name;
	const message = `code: minted has no Pygments lexer for "${name}" — LaTeX prints that code as plain text`;
	if (!getWarnings().includes(message)) addWarning(message);
	return 'text';
}

// True while a heading's content renders. A heading's text is a MOVING
// argument — \section{…} writes it to the .aux and the .toc — and there
// \mintinline's \verb-style delimiters break: `\section{\mintinline{text}|x|}`
// stops pdflatex ("Argument of \FV@… has an extra }"). minted 3 copes with
// them in \textbf, \emph, \footnote and \href, so headings are the one case.
let inHeading = false;

// Inline code in a heading. Brace delimiters survive a moving argument and the
// .toc round trip, provided TeX can read the code as one balanced group: no
// `#` or `%` (their meaning is fixed when the argument is read), no backslash,
// balanced braces. Anything else is typeset as \texttt with every special
// escaped — the same monospace, unhighlighted, as inline `text` code is anyway.
function headingCode(lang, code) {
	let depth = 0;
	for (const c of code) {
		if (c === '{') depth++;
		else if (c === '}' && --depth < 0) break;
	}
	if (depth === 0 && !/[#%\\]/.test(code)) {
		requirePackage('minted');
		return `\\mintinline{${lang}}{${code}}`;
	}
	return `\\texttt{${escapeTexText(code)}}`;
}

// A <style> element is the page's CSS, with nothing to print.
const STYLE_ELEMENT = /<style\b[^>]*>[\s\S]*?<\/style>[ \t]*\n?/gi;

// Block-level text, rendered as the paragraph marked would wrap it in — ONCE.
// Text inside a list item is lexed as `text` tokens, not paragraphs (marked's
// lexer is not at the top level there), and so is the body of any block
// nested in one: a callout, an @begin environment. marked's parser renders
// such a token and then wraps the RESULT in a paragraph, as one text token
// flagged `escaped` (Parser.parse, `top`), which text() escaped a second time:
// every `&` and `#` became `\\&` / `\\#` (a line break, then an alignment tab,
// which stops pdfLaTeX), and a `#` in inline code printed as `\#`. The
// `escaped` flag can't mark that wrap: marked flags ordinary text `escaped`
// too, inside an inline <code>, <kbd>, <pre> or <script> and in every
// paragraph after one left open, and that text is not yet LaTeX.
// An extension renderer is consulted before marked's own handling, so the
// token becomes a paragraph here, unrendered, and is escaped once. Block-level
// text is the kind that carries inline `tokens` (as smart-typography.js and
// latex-lint.js also tell it apart). Everything else — HTML, inline text —
// returns false and goes on to the renderer, unchanged.
const blockText = {
	name: 'text',
	renderer(token) {
		if (!global.isLatex || !Array.isArray(token.tokens)) return false;
		return this.parser.renderer.paragraph({ type: 'paragraph', raw: token.raw, text: token.text, tokens: token.tokens });
	},
};
marked.use({ extensions: [blockText] });

const latexRenderer = {

	// Raw HTML reaches the .tex as written (marked's own rule), but for its
	// <style> elements: a document's CSS printed as text in the PDF (and a book
	// chapter's, before it). A block that held nothing else renders nothing.
	html(token) {
		const text = String(token.text ?? '');
		if (!/<style\b/i.test(text)) return text;
		const left = text.replace(STYLE_ELEMENT, '');
		return left.trim() ? left : '';
	},

	paragraph(token) {
		return `${this.parser.parseInline(token.tokens)}\n\n`;
	},

	heading(token) {
		let content;
		inHeading = true;
		try {
			content = this.parser.parseInline(token.tokens);
		} finally {
			inHeading = false;
		}
		const command = commandForDepth(token.depth);

		// Check for {-} suffix, which signals an unnumbered heading.
		let starred = '';
		if (/\s*\{-\}\s*$/.test(content)) {
			content = content.replace(/\s*\{-\}\s*$/, '');
			starred = '*';
		}

		return `\\${command}${starred}{${content}}\n\n`;
	},

	strong(token) {
		return `\\textbf{${this.parser.parseInline(token.tokens)}}`;
	},

	em(token) {
		return `\\emph{${this.parser.parseInline(token.tokens)}}`;
	},

	codespan(token) {
		const lang = mintedLanguage(configManager.get('Code language'));
		const code = token.text;
		if (inHeading) return headingCode(lang, code);
		requirePackage('minted');
		// Use a delimiter the code doesn't contain. The brace form
		// \mintinline{lang}{code} breaks on a literal `}` in the code (the group
		// closes early); a \verb-style delimiter avoids that.
		const delim = MINTINLINE_DELIMS.find(c => !code.includes(c));
		if (delim) return `\\mintinline{${lang}}${delim}${code}${delim}`;
		// Pathological: code contains every candidate delimiter. Fall back to the
		// brace form, which still works when the braces in the code are balanced.
		return `\\mintinline{${lang}}{${code}}`;
	},

	code(token) {
		// Prefer the fence's named language (```javascript) over the
		// document-wide default. Requires \usepackage{minted} in the
		// preamble (declared here) and pdflatex -shell-escape at compile time.
		requirePackage('minted');
		const lang = mintedLanguage(token.lang);
		return `\\begin{minted}{${lang}}\n${token.text}\n\\end{minted}\n\n`;
	},

	link(token) {
		requirePackage('hyperref');
		const text = this.parser.parseInline(token.tokens);
		return `\\href{${escapeLatex(token.href)}}{${text}}`;
	},

	image(token) {
		// A bare image is just the graphic — NOT a floating, numbered figure.
		// Use @begin(figure) (see floats.js) for a captioned, numbered,
		// referenceable float; nesting \includegraphics there avoids a figure
		// inside a figure.
		// A remote image or an SVG can't be included; latex-graphics.js links
		// to it instead, with a warning, rather than emit a document that will
		// not compile.
		return latexGraphic({ src: token.href, alt: token.text, what: 'image', options: () => '[width=\\textwidth]' });
	},

	blockquote(token) {
		const body = this.parser.parse(token.tokens).trimEnd();
		return `\\begin{quote}\n${body}\n\\end{quote}\n\n`;
	},

	list(token) {
		const env = token.ordered ? 'enumerate' : 'itemize';
		let body = '';
		for (const item of token.items) {
			body += this.listitem(item);
		}
		return `\\begin{${env}}\n${body}\\end{${env}}\n\n`;
	},

	listitem(token) {
		const content = this.parser.parse(token.tokens);
		return `\\item ${content.trim()}\n`;
	},

	table(token) {
		// Fallback for marked's built-in `table` token. The two table
		// extensions in `marked-extended-tables-headerless.js` intercept
		// most tables and render directly to LaTeX, but marked's GFM
		// tokenizer is more permissive (e.g. accepts rows without trailing
		// pipes) and falls through to this renderer for those edge cases.
		const ncols = token.header.length;
		const aligns = token.align.map(a => {
			if (a === 'center') return 'c';
			if (a === 'right') return 'r';
			return 'l';
		});
		const colspec = aligns.join('');

		// booktabs rules (\toprule/\midrule/\bottomrule) — the publication
		// look, not \hline's spreadsheet look. Same rules in both table paths
		// (see renderTableLatex in marked-extended-tables-headerless.js).
		requirePackage('booktabs');
		let tex = `\\begin{tabular}{${colspec}}\n\\toprule\n`;

		// Header row
		const headerCells = token.header.map(cell =>
			this.parser.parseInline(cell.tokens)
		);
		tex += headerCells.join(' & ') + ' \\\\\n\\midrule\n';

		// Body rows
		for (const row of token.rows) {
			const cells = row.map(cell =>
				this.parser.parseInline(cell.tokens)
			);
			tex += cells.join(' & ') + ' \\\\\n';
		}

		tex += '\\bottomrule\n\\end{tabular}\n\n';
		return tex;
	},

	hr(token) {
		return '\\bigskip\\noindent\\rule{\\textwidth}{0.4pt}\\bigskip\n\n';
	},

	br(token) {
		return '\\\\\n';
	},

	text(token) {
		// A text token may contain inline sub-tokens (e.g. when it appears
		// inside a paragraph that has been partially parsed).
		if (token.tokens) {
			return this.parser.parseInline(token.tokens);
		}
		return escapeLatex(token.text);
	}
};

export default latexRenderer;
